// Local shim for html5-qrcode
// Prevents 404 and attempts to load the real library from CDN.
(function(){
    try {
        var cdnUrl = 'https://unpkg.com/html5-qrcode@2.3.8/minified/html5-qrcode.min.js';
        var script = document.createElement('script');
        script.src = cdnUrl;
        script.async = true;
        script.onload = function(){
            console.info('html5-qrcode loaded from CDN');
        };
        script.onerror = function(){
            console.warn('html5-qrcode failed to load from CDN. Camera scanning will be unavailable.');
        };
        document.head.appendChild(script);
    } catch (e) {
        console.warn('html5-qrcode shim error', e);
    }
})();
